let cursor = '';
let allRecords = [];
let hasMore = true;
let pageCount = 0;

while (hasMore) {
  let url = 'https://crm-api.aqaryone.com/api/v4/modules/Leads/records?per_page=100';
  if (cursor) url += '&cursor=' + encodeURIComponent(cursor);

  const response = await $http.request({
    method: 'GET',
    url: url,
    headers: {
      'Authorization': token,
      'X-Entity-Id': '1'
    }
  });

  const body = Array.isArray(response) ? response[0] : response;
  const records = body.records || [];
  allRecords = allRecords.concat(records);
  pageCount++;

  hasMore = body.pagination?.has_more === true;
  cursor = body.pagination?.next_cursor ?? '';

  if (!cursor && hasMore) break;
  if (pageCount >= 200) break;
}

return allRecords.map(r => ({ json: r }));

